# test-fuse-operations.ps1 -- Exercise FUSE mount file I/O operations (Windows).
#
# Usage: .\test-fuse-operations.ps1 [-MountPoint <path>]
#   -MountPoint  Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#
# Tests: create, read, overwrite, mkdir, nested write, binary round-trip,
#        rename file, rename directory, move file across directories,
#        delete file, delete directory.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox"
)

$ErrorActionPreference = "Continue"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== FUSE File I/O Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host ""

# ---- Test 1: Create and read text file ----
Write-Host "--- Test 1: Create and read text file ---"
try {
    Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Hello from CI" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 3
    $Content = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw -ErrorAction Stop
    if ($null -ne $Content -and $Content.Trim() -eq "Hello from CI") {
        Test-Pass "Create and read text file"
    } else {
        Test-Fail "Create and read text file (got: '$Content')"
    }
} catch {
    Test-Fail "Create and read text file (exception: $($_.Exception.Message))"
}

# ---- Test 2: Create directory ----
Write-Host "--- Test 2: Create directory ---"
try {
    New-Item -ItemType Directory -Path "$MountPoint\e2e-folder" -Force -ErrorAction Stop | Out-Null
    if (Test-Path "$MountPoint\e2e-folder" -PathType Container) {
        Test-Pass "Create directory"
    } else {
        Test-Fail "Create directory"
    }
} catch {
    Test-Fail "Create directory (exception: $($_.Exception.Message))"
}

# ---- Test 3: Write file in subdirectory ----
Write-Host "--- Test 3: Write file in subdirectory ---"
try {
    Set-Content -Path "$MountPoint\e2e-folder\nested.txt" -Value "Nested content" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 3
    $Nested = Get-Content -Path "$MountPoint\e2e-folder\nested.txt" -Raw -ErrorAction Stop
    if ($null -ne $Nested -and $Nested.Trim() -eq "Nested content") {
        Test-Pass "Write file in subdirectory"
    } else {
        Test-Fail "Write file in subdirectory (got: '$Nested')"
    }
} catch {
    Test-Fail "Write file in subdirectory (exception: $($_.Exception.Message))"
}

# ---- Test 4: Overwrite file (modify) ----
Write-Host "--- Test 4: Overwrite file ---"
try {
    Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Modified content" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 5
    $Modified = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw -ErrorAction Stop
    if ($null -ne $Modified -and $Modified.Trim() -eq "Modified content") {
        Test-Pass "Overwrite file"
    } else {
        Test-Fail "Overwrite file (got: '$Modified')"
    }
} catch {
    Test-Fail "Overwrite file (exception: $($_.Exception.Message))"
}

# ---- Test 5: Binary file round-trip ----
Write-Host "--- Test 5: Binary file round-trip ---"
try {
    $TempBinary = "$env:TEMP\e2e-binary.bin"
    $MountBinary = "$MountPoint\e2e-binary.bin"
    $Bytes = New-Object byte[] (256 * 1024)
    $Rng = [System.Security.Cryptography.RNGCryptoServiceProvider]::new()
    $Rng.GetBytes($Bytes)
    $Rng.Dispose()
    [System.IO.File]::WriteAllBytes($TempBinary, $Bytes)
    Copy-Item -Path $TempBinary -Destination $MountBinary -ErrorAction Stop
    Start-Sleep -Seconds 5
    $HashOrig = (Get-FileHash -Path $TempBinary -Algorithm SHA256).Hash
    $HashMount = (Get-FileHash -Path $MountBinary -Algorithm SHA256).Hash
    if ($HashOrig -eq $HashMount) {
        Test-Pass "Binary file round-trip (256KB)"
    } else {
        Test-Fail "Binary file round-trip (orig: $HashOrig, mount: $HashMount)"
    }
} catch {
    Test-Fail "Binary file round-trip (exception: $($_.Exception.Message))"
}

# ---- Test 6: Rename file ----
Write-Host "--- Test 6: Rename file ---"
try {
    Move-Item -Path "$MountPoint\e2e-test.txt" -Destination "$MountPoint\e2e-renamed.txt" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    $OldExists = Test-Path "$MountPoint\e2e-test.txt"
    $NewExists = Test-Path "$MountPoint\e2e-renamed.txt"
    if (-not $OldExists -and $NewExists) {
        $Renamed = Get-Content -Path "$MountPoint\e2e-renamed.txt" -Raw
        if ($Renamed.Trim() -eq "Modified content") {
            Test-Pass "Rename file"
        } else {
            Test-Fail "Rename file (content changed: '$Renamed')"
        }
    } else {
        Test-Fail "Rename file (old exists: $OldExists, new exists: $NewExists)"
    }
} catch {
    Test-Fail "Rename file (exception: $($_.Exception.Message))"
}

# ---- Test 6b: Rename directory ----
Write-Host "--- Test 6b: Rename directory ---"
try {
    Move-Item -Path "$MountPoint\e2e-folder" -Destination "$MountPoint\e2e-folder-renamed" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    $OldDirExists = Test-Path "$MountPoint\e2e-folder" -PathType Container
    $NewDirExists = Test-Path "$MountPoint\e2e-folder-renamed" -PathType Container
    if (-not $OldDirExists -and $NewDirExists) {
        # Verify nested content is still accessible
        $NestedAfter = Get-Content -Path "$MountPoint\e2e-folder-renamed\nested.txt" -Raw -ErrorAction Stop
        if ($null -ne $NestedAfter -and $NestedAfter.Trim() -eq "Nested content") {
            Test-Pass "Rename directory (with nested content preserved)"
        } else {
            Test-Fail "Rename directory (nested content changed: '$NestedAfter')"
        }
    } else {
        Test-Fail "Rename directory (old exists: $OldDirExists, new exists: $NewDirExists)"
    }
} catch {
    Test-Fail "Rename directory (exception: $($_.Exception.Message))"
}

# ---- Test 6c: Move file across directories ----
Write-Host "--- Test 6c: Move file across directories ---"
try {
    New-Item -ItemType Directory -Path "$MountPoint\e2e-dest-folder" -Force -ErrorAction Stop | Out-Null
    Move-Item -Path "$MountPoint\e2e-folder-renamed\nested.txt" -Destination "$MountPoint\e2e-dest-folder\nested.txt" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    $SourceExists = Test-Path "$MountPoint\e2e-folder-renamed\nested.txt"
    $DestExists = Test-Path "$MountPoint\e2e-dest-folder\nested.txt"
    if (-not $SourceExists -and $DestExists) {
        $Moved = Get-Content -Path "$MountPoint\e2e-dest-folder\nested.txt" -Raw -ErrorAction Stop
        if ($null -ne $Moved -and $Moved.Trim() -eq "Nested content") {
            Test-Pass "Move file across directories"
        } else {
            Test-Fail "Move file across directories (content changed: '$Moved')"
        }
    } else {
        Test-Fail "Move file across directories (source exists: $SourceExists, dest exists: $DestExists)"
    }
} catch {
    Test-Fail "Move file across directories (exception: $($_.Exception.Message))"
}

# ---- Test 7: Delete file ----
Write-Host "--- Test 7: Delete file ---"
try {
    Remove-Item -Path "$MountPoint\e2e-renamed.txt" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    if (-not (Test-Path "$MountPoint\e2e-renamed.txt")) {
        Test-Pass "Delete file"
    } else {
        Test-Fail "Delete file (still exists)"
    }
} catch {
    Test-Fail "Delete file (exception: $($_.Exception.Message))"
}

# ---- Test 8: Delete directories ----
Write-Host "--- Test 8: Delete directories ---"
try {
    # Delete e2e-dest-folder (contains nested.txt)
    Remove-Item -Path "$MountPoint\e2e-dest-folder\nested.txt" -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    [System.IO.Directory]::Delete("$MountPoint\e2e-dest-folder")
    Start-Sleep -Seconds 2

    # Delete e2e-folder-renamed (now empty after move)
    [System.IO.Directory]::Delete("$MountPoint\e2e-folder-renamed")
    Start-Sleep -Seconds 2

    $DestDirExists = Test-Path "$MountPoint\e2e-dest-folder" -PathType Container
    $RenamedDirExists = Test-Path "$MountPoint\e2e-folder-renamed" -PathType Container
    if (-not $DestDirExists -and -not $RenamedDirExists) {
        Test-Pass "Delete directories"
    } else {
        Test-Fail "Delete directories (e2e-dest-folder exists: $DestDirExists, e2e-folder-renamed exists: $RenamedDirExists)"
    }
} catch {
    Write-Host "  Directory::Delete failed: $($_.Exception.Message)"
    Write-Host "  Trying cmd /c rd fallback..."
    try {
        cmd /c rd "$MountPoint\e2e-dest-folder" 2>&1
        cmd /c rd "$MountPoint\e2e-folder-renamed" 2>&1
        Start-Sleep -Seconds 2
        $DestDirExists = Test-Path "$MountPoint\e2e-dest-folder" -PathType Container
        $RenamedDirExists = Test-Path "$MountPoint\e2e-folder-renamed" -PathType Container
        if (-not $DestDirExists -and -not $RenamedDirExists) {
            Test-Pass "Delete directories (via rd fallback)"
        } else {
            Test-Fail "Delete directories (still exist after rd: e2e-dest-folder=$DestDirExists, e2e-folder-renamed=$RenamedDirExists)"
        }
    } catch {
        Test-Fail "Delete directories (exception: $($_.Exception.Message))"
    }
}

# ---- Test 9: Cleanup ----
Write-Host "--- Test 9: Cleanup ---"
Remove-Item -Path $MountBinary -Force -ErrorAction SilentlyContinue
Remove-Item -Path $TempBinary -Force -ErrorAction SilentlyContinue
if ((-not (Test-Path $MountBinary)) -and (-not (Test-Path $TempBinary))) {
    Test-Pass "Cleanup"
} else {
    Test-Fail "Cleanup (artifacts still exist)"
}

# ---- Summary ----
Write-Host ""
Write-Host "=== FUSE File I/O Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=============================="

exit $Fail
